/* bop Aero embed: news
 * Built from components/news/src/ — DO NOT EDIT THIS FILE.
 * Edit the source or a data/news/*.json entry, then: python3 tools/build.py news
 * Entries in this build: 2026-09-18-sample-post
 */
(function () {
  var NAME = "news";
  var STYLE_ID = 'bopaero-style-' + NAME;
  var CSS = "/* ============================================================================\n   bop Aero embed design tokens \u2014 ONE definition, prepended to every component\n   by tools/build.py. Edit here, rebuild, and both components change together.\n\n   WHY THIS FILE EXISTS: the components previously declared almost no colours or\n   fonts, so every unspecified property silently inherited whatever Squarespace\n   supplied. That produced two customer-facing bugs in one week - orange footnotes\n   and an orange full-size usage note - each fixed one at a time. Tokens make the\n   whole class of bug impossible: nothing is left to inherit by accident.\n\n   Values are MEASURED from bopaero.com computed styles (2026-09-15), not guessed.\n   ========================================================================== */\n.bop-embed {\n  /* brand ------------------------------------------------------------------ */\n  --bop-orange:        #FF6700;\n  --bop-orange-ink:    #fff;\n  /* Derived, so a brand tweak needs one edit. color-mix keeps hover/active in\n     step with --bop-orange instead of drifting as hand-picked hex values. */\n  --bop-orange-hover:  color-mix(in srgb, var(--bop-orange) 88%, #000);\n  --bop-orange-soft:   color-mix(in srgb, var(--bop-orange) 12%, #fff);\n  --bop-navy:          #003767;\n  --bop-ink:           #282D30;\n\n  /* surfaces --------------------------------------------------------------- */\n  /* Raymond 2026-09-18: the calculator now wears the same navy the narrative\n     sections use (measured #003767 on the live pages), so the embed reads as part\n     of the page rather than a tan island in it. The card surface is only one step\n     lighter on purpose - enough to separate, not enough to stripe. */\n  --bop-panel:         #003767;   /* was #E9CEB0 tan */\n  /* Cards carry ALL the structure now. Raymond made the PRICING section the same\n     navy as the panel, so the panel's frame and shadow no longer separate anything\n     and #0A4478 was doing that job at 1.21:1 - which would vanish on a phone in\n     daylight. #0E4D8C is 1.41:1 against the panel: still one family, but each block\n     reads as its own surface. White stays 8.54:1 on it, muted 5.55:1, both AA. */\n  --bop-surface:       #0E4D8C;   /* cards sitting on the panel */\n  --bop-card:          #fff;      /* INPUT fields stay white: legible, and obviously editable */\n  --bop-line:          rgba(255,255,255,.18);\n\n  /* text ------------------------------------------------------------------- */\n  /* Contrast measured against the surface, not guessed: white 9.95:1, muted\n     6.46:1. Orange is 3.41:1 there, which is large-text only - so it is used for\n     buttons and marks, never for body copy. */\n  --bop-text:          #FFFFFF;\n  --bop-text-muted:    #C3D2E2;\n  --bop-label:         #DCE6F1;\n\n  /* type ------------------------------------------------------------------- */\n  --bop-font-head: \"Archivo Black\", \"Arial Black\", system-ui, sans-serif;\n  --bop-font-body: proxima-nova, \"Proxima Nova\", -apple-system, BlinkMacSystemFont,\n                   \"Segoe UI\", Helvetica, Arial, sans-serif;\n  --bop-head-ls:   -0.02em;       /* the site sets a tight negative tracking */\n\n  /* geometry --------------------------------------------------------------- */\n  --bop-radius:      10px;\n  --bop-radius-pill: 300px;       /* site buttons are full pills */\n  --bop-gap:         12px;\n\n  /* feedback --------------------------------------------------------------- */\n  --bop-focus:       var(--bop-navy);\n  --bop-warn-text:   #7a4a00;\n  --bop-warn-bg:     #fff6e5;\n  --bop-warn-edge:   #e8820c;\n\n  --bop-shadow:      0 1px 3px rgba(0,0,0,.10), 0 6px 18px rgba(0,0,0,.06);\n}\n\n/* Motion is opt-out, not opt-in. */\n@media (prefers-reduced-motion: reduce) {\n  .bop-embed *, .bop-embed *::before, .bop-embed *::after {\n    animation-duration: .001ms !important;\n    transition-duration: .001ms !important;\n  }\n}\n\n/* ---- News list ------------------------------------------------------------\n   Sits on the navy news section, so it inherits the same surface tokens the\n   calculator uses - one palette, one place to change it. */\n.news-root { font-family: var(--bop-font-body); color: var(--bop-text);\n  /* The page block runs the full content width, but a 1400px line of body copy is\n     unreadable. Cap the measure and centre it; narrower mounts are unaffected. */\n  max-width: 860px; margin-inline: auto; }\n\n.news-list { display: flex; flex-direction: column; gap: 14px; }\n\n.news-item {\n  background: var(--bop-surface);\n  border-radius: var(--bop-radius);\n  padding: 18px 20px;\n  display: grid;\n  grid-template-columns: 1fr;\n  gap: 10px;\n}\n.news-item.has-image { grid-template-columns: 220px 1fr; align-items: start; }\n\n.news-item img {\n  width: 100%; height: auto; display: block;\n  border-radius: 6px; background: rgba(255,255,255,.06);\n}\n\n.news-meta {\n  display: flex; align-items: center; gap: 10px; flex-wrap: wrap;\n  font-size: 12px; letter-spacing: .06em; text-transform: uppercase;\n  color: var(--bop-text-muted);\n}\n.news-tag {\n  border: 1px solid var(--bop-line); border-radius: var(--bop-radius-pill);\n  padding: 2px 10px; letter-spacing: .06em;\n}\n.news-title {\n  font-family: var(--bop-font-head); letter-spacing: var(--bop-head-ls);\n  font-size: 21px; line-height: 1.25; margin: 0; color: var(--bop-text);\n}\n.news-body { margin: 0; font-size: 15px; line-height: 1.55; color: var(--bop-text); }\n.news-body p { margin: 0 0 10px; }\n.news-body p:last-child { margin-bottom: 0; }\n.news-body a, .news-more { color: var(--bop-orange); }\n\n.news-more {\n  display: inline-block; margin-top: 4px; font-weight: 600;\n  text-decoration: none; border-bottom: 1px solid currentColor;\n}\n.news-more:hover { color: var(--bop-orange-hover); }\n.news-item :focus-visible { outline: 2px solid #fff; outline-offset: 3px; }\n\n.news-empty { color: var(--bop-text-muted); font-style: italic; }\n\n/* Container query, not a viewport one: the list can sit in a narrow column on a\n   wide page (a teaser beside other content), where a media query never fires. */\n.news-root { container-type: inline-size; container-name: bopnews; }\n@container bopnews (max-width: 560px) {\n  .news-item.has-image { grid-template-columns: 1fr; }\n  .news-title { font-size: 19px; }\n}\n\n.news-heading {\n  font-family: var(--bop-font-head);\n  font-size: 30px;\n  line-height: 1.15;\n  margin: 0 0 18px;\n  color: var(--bop-text);\n}\n@container bopnews (max-width: 520px) {\n  .news-heading { font-size: 24px; }\n}\n";
  var HTML = "<!-- Filled by initNews(). Empty on purpose: the list is data, not markup. -->\n<div class=\"bop-embed news-root\">\n  <div class=\"news-list\"></div>\n  <p class=\"news-empty\" hidden>No posts yet.</p>\n</div>\n";
  var ITEMS = [
{
"_sample": "PLACEHOLDER \u2014 Raymond: edit or delete this file. It exists so the page renders something before the first real post. Copy it to data/news/YYYY-MM-DD-your-slug.json, and the filename becomes the anchor: bopaero.com/news#YYYY-MM-DD-your-slug",
"date": "2026-09-18",
"title": "Sample post \u2014 replace me",
"tag": "Program",
"body": "<p>This is a placeholder so the news page has something to render. Replace the text, change the date, and give the file a new name.</p><p>Body copy accepts simple formatting: <strong>bold</strong>, <em>italics</em>, links, and lists.</p>",
"image": "",
"imageAlt": "",
"link": "",
"linkText": "",
"slug": "2026-09-18-sample-post"
}
];

  function mount(el) {
    if (el.getAttribute('data-bopaero-mounted')) return;
    el.setAttribute('data-bopaero-mounted', '1');
    if (CSS && !document.getElementById(STYLE_ID)) {
      var st = document.createElement('style');
      st.id = STYLE_ID; st.textContent = CSS;
      document.head.appendChild(st);
    }
    el.innerHTML = HTML;
    /* A collection component renders MANY entries, so the mount carries filters
       rather than an id: data-limit trims the list (a teaser elsewhere on the
       site) and data-tag narrows it. Same data, several placements. */
    var opts = {
      limit: parseInt(el.getAttribute('data-limit') || '0', 10) || 0,
      tag: el.getAttribute('data-tag') || ''
    };
    try { initNews(el, ITEMS.slice(), opts); }
    catch (e) { console.error('[bopaero:' + NAME + '] failed', e); }
  }

  function boot() {
    var els = document.querySelectorAll('[data-embed="' + NAME + '"]');
    if (!els.length) {
      console.warn('[bopaero:' + NAME + '] no [data-embed="' + NAME + '"] mount found');
      return;
    }
    Array.prototype.forEach.call(els, mount);
  }

  /* ── engine (verbatim from src/component.js) ───────────────────────── */
  /* ============================================================================
     bop Aero embed telemetry — aggregate only, prepended to every component.

     WHAT IT COLLECTS: how far down a page a visit scrolls, where clicks land as a
     coarse grid position, which named control was clicked, and a handful of
     calculator milestones. Plus page path and whether the viewport is phone-sized.

     WHAT IT DOES NOT COLLECT, BY DESIGN: no cookies, no visitor or session id, no
     fingerprint, no form values, no keystrokes, no session replay. Two visits are
     indistinguishable in the data. That is deliberate - it keeps this inside the
     "usage data / network activity" the existing privacy notice already describes,
     so no new processor and no policy redraft. The tracker this replaces (an
     inherited Hotjar) recorded full session replays into an account Raymond did
     not control; the whole point of building our own is not to repeat that.

     Runs ONCE per page even when several embeds are present. Sends nothing until
     ENDPOINT is set, so the data shape can be proven locally first.
     ========================================================================== */
  (function () {
    if (window.__bopTelemetry) return;          // one collector per page

    var ENDPOINT = 'https://bopaero-telemetry.compilotrc.workers.dev/collect';
    var DEBUG = /[?&]bopdebug=1/.test(location.search);
    var GRID_X = 20, GRID_Y = 40;               // click bins: coarse on purpose
    var MILESTONES = [25, 50, 75, 100];

    var events = [];
    var seenScroll = {};
    var sent = false;

    function ctx() {
      return {
        path: location.pathname,
        view: window.innerWidth <= 900 ? 'phone' : 'desktop'
      };
    }
    function push(type, data) {
      if (events.length >= 200) return;         // bound the payload, always
      events.push({ t: type, d: data || {} });
      if (DEBUG) console.log('[bop:telemetry]', type, data || {});
    }

    /* ── scroll depth ──────────────────────────────────────────────────────
       Milestones rather than a continuous position: it answers "how far do
       visitors get" without describing any individual's path down the page. */
    function scrollDepth() {
      var doc = document.documentElement;
      var max = Math.max(1, doc.scrollHeight - window.innerHeight);
      var pct = Math.min(100, Math.round(((window.scrollY || doc.scrollTop || 0) / max) * 100));
      for (var i = 0; i < MILESTONES.length; i++) {
        var m = MILESTONES[i];
        if (pct >= m && !seenScroll[m]) { seenScroll[m] = 1; push('scroll', { pct: m }); }
      }
    }

    /* ── clicks ────────────────────────────────────────────────────────────
       Position is binned to a 20x40 grid of the DOCUMENT, not exact pixels, so
       the report can draw density without the data describing a precise pointer
       trace. `el` names the control when it is one we care about. */
    function describe(node) {
      var el = node;
      for (var i = 0; i < 6 && el && el.nodeType === 1; i++) {
        if (el.id) return '#' + el.id;
        if (el.getAttribute && el.getAttribute('data-embed')) return '[' + el.getAttribute('data-embed') + ']';
        if (el.tagName === 'A' || el.tagName === 'BUTTON' || el.tagName === 'SELECT') {
          var txt = (el.innerText || el.value || '').trim().replace(/\s+/g, ' ').slice(0, 28);
          return el.tagName.toLowerCase() + (txt ? ':' + txt : '');
        }
        el = el.parentElement;
      }
      return 'other';
    }
    function onClick(e) {
      var doc = document.documentElement;
      var w = Math.max(1, doc.scrollWidth), h = Math.max(1, doc.scrollHeight);
      push('click', {
        x: Math.min(GRID_X - 1, Math.floor((e.pageX / w) * GRID_X)),
        y: Math.min(GRID_Y - 1, Math.floor((e.pageY / h) * GRID_Y)),
        el: describe(e.target)
      });
    }

    /* ── delivery ──────────────────────────────────────────────────────────
       sendBeacon on the way out: it survives navigation, where fetch does not.
       visibilitychange fires on mobile where unload often does not. */
    function flush() {
      if (sent || !events.length) return;
      sent = true;
      scrollDepth();          /* final depth before we stop measuring */
      var payload = { v: 1, ctx: ctx(), events: events };
      if (DEBUG) console.log('[bop:telemetry] FLUSH', JSON.stringify(payload));
      if (!ENDPOINT) return;                    // nothing configured: collect, never send
      try {
        /* text/plain, NOT application/json. A non-safelisted content type forces a
           CORS preflight, and sendBeacon cannot perform one - the browser drops the
           request with no error anywhere. It reported "sent" client-side and nothing
           ever arrived. The body is still JSON; the Worker parses it regardless. */
        var blob = new Blob([JSON.stringify(payload)], { type: 'text/plain;charset=UTF-8' });
        if (!navigator.sendBeacon || !navigator.sendBeacon(ENDPOINT, blob)) {
          fetch(ENDPOINT, { method: 'POST', body: blob, keepalive: true, mode: 'no-cors' });
        }
      } catch (e) { /* telemetry must never break the page */ }
    }

    try {
      window.addEventListener('scroll', scrollDepth, { passive: true });
      /* A low-frequency sampler as well as the scroll listener. Scroll events are
         throttled or suppressed entirely in some contexts - background tabs, some
         webviews, and any automated driver - and depth would then silently never
         record. Sampling is cheap, catches programmatic scrolling too, and stops
         as soon as every milestone is seen or the page is on its way out. */
      var sampler = setInterval(function () {
        scrollDepth();
        if (seenScroll[100]) clearInterval(sampler);
      }, 1000);
      document.addEventListener('click', onClick, true);
      document.addEventListener('visibilitychange', function () {
        if (document.visibilityState === 'hidden') flush();
      });
      window.addEventListener('pagehide', flush);
      scrollDepth();

      window.__bopTelemetry = {
        event: function (name, data) { push(name, data); },
        dump: function () { return { ctx: ctx(), events: events }; }
      };
    } catch (e) {
      window.__bopTelemetry = { event: function () {}, dump: function () { return null; } };
      if (DEBUG) console.warn('[bop:telemetry] disabled:', e.message);
    }
  })();

  /* News list.
   *
   * Receives every post, newest first (the build does the sorting, so a post cannot
   * be filed out of order by hand), plus the mount's filters. The same data therefore
   * serves /news in full and a short teaser anywhere else on the site.
   */
  function initNews(root, items, opts) {
    var listEl = root.querySelector('.news-list');
    var emptyEl = root.querySelector('.news-empty');

    function esc(s) {
      return String(s == null ? '' : s)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
    }

    /* Post bodies are authored HTML in the data file, so only a known-safe subset is
       allowed through. The files are ours, but a component that injects arbitrary
       HTML into a customer-facing page is a habit worth not forming, and this also
       means a stray unclosed tag damages one post instead of the whole page. */
    var ALLOWED = /^(p|br|strong|b|em|i|ul|ol|li|a|span)$/i;
    function richText(html) {
      var src = String(html == null ? '' : html);
      var doc = document.createElement('div');
      doc.innerHTML = src;
      (function walk(node) {
        var kids = Array.prototype.slice.call(node.childNodes);
        kids.forEach(function (child) {
          if (child.nodeType === 3) return;                 /* text is fine */
          if (child.nodeType !== 1) { child.remove(); return; }
          if (!ALLOWED.test(child.tagName)) {                /* unwrap, keep the words */
            while (child.firstChild) node.insertBefore(child.firstChild, child);
            child.remove();
            return;
          }
          Array.prototype.slice.call(child.attributes).forEach(function (a) {
            var n = a.name.toLowerCase();
            var bad = n.indexOf('on') === 0 ||
                      ((n === 'href' || n === 'src') && /^\s*javascript:/i.test(a.value));
            if (bad || (n !== 'href' && n !== 'title' && n !== 'target' && n !== 'rel')) {
              child.removeAttribute(a.name);
            }
          });
          walk(child);
        });
      })(doc);
      return doc.innerHTML;
    }

    function fmtDate(iso) {
      /* Noon, so a timezone offset cannot roll the displayed day backwards. */
      var d = new Date(iso + 'T12:00:00');
      if (isNaN(d)) return iso;
      return d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
    }

    /* The page heading ships with the component so /news has no Squarespace title to
       keep in sync. data-heading="Latest news" retitles it; data-heading="" drops it,
       which is what a teaser mount under its own section header wants. */
    var headingAttr = root.getAttribute('data-heading');
    var headingText = headingAttr === null ? 'News' : headingAttr;
    if (headingText) {
      var h = document.createElement('h2');
      h.className = 'news-heading';
      h.textContent = headingText;
      listEl.parentNode.insertBefore(h, listEl);
    }

    var posts = items.filter(function (p) {
      return !opts.tag || String(p.tag || '').toLowerCase() === opts.tag.toLowerCase();
    });
    if (opts.limit > 0) posts = posts.slice(0, opts.limit);

    if (!posts.length) { emptyEl.hidden = false; return; }

    posts.forEach(function (p) {
      var art = document.createElement('article');
      art.className = 'news-item' + (p.image ? ' has-image' : '');
      /* A stable id per post, so one announcement can be linked to directly -
         bopaero.com/news#2026-09-18-slug - which is what gets pasted into an email. */
      art.id = p.slug;

      var html = '';
      if (p.image) {
        html += '<img src="' + esc(p.image) + '" alt="' + esc(p.imageAlt || p.title) +
                '" loading="lazy">';
      }
      html += '<div class="news-text">' +
                '<div class="news-meta"><time datetime="' + esc(p.date) + '">' +
                  esc(fmtDate(p.date)) + '</time>' +
                  (p.tag ? '<span class="news-tag">' + esc(p.tag) + '</span>' : '') +
                '</div>' +
                '<h3 class="news-title">' + esc(p.title) + '</h3>' +
                '<div class="news-body">' + richText(p.body) + '</div>' +
                (p.link ? '<a class="news-more" href="' + esc(p.link) + '">' +
                          esc(p.linkText || 'Read more') + ' →</a>' : '') +
              '</div>';
      art.innerHTML = html;
      listEl.appendChild(art);
    });

    /* Deep link: if the page was opened at #slug, bring that post into view. */
    if (location.hash && window.CSS && CSS.escape) {
      var target = root.querySelector('#' + CSS.escape(location.hash.slice(1)));
      if (target) setTimeout(function () { target.scrollIntoView({ block: 'center' }); }, 120);
    }
  }

  if (document.readyState === 'loading')
    document.addEventListener('DOMContentLoaded', boot);
  else boot();
})();
